rows["Locales/enUS.lua"]={bytes=246244,hash=2791749068,oldBytes=239014,oldHash=4148028330,edits={{at=180799,current="L['Workbench Help'] = 'Workbench Help'\n\nL['Navigation'] = 'Navigation'\n\nL['Help.Window.navigation'] = 'Choose tabs to browse Rotations, General, Conditions, Functions, Effects, Item Sets, Announces, Profiles and Integrations. Each tab has its own Help for page controls. Search and filters belong to the current page. Built In entries remain read-only; Duplicate creates an editable copy.'\n\nL['Help.Window.scale'] = 'Scale changes the whole workbench and its child windows from 70% to 130%. Drag the top-left slider or enter an integer percentage and press Enter. Escape restores the saved scale text. Drag the title bar to move; drag the lower-right corner to resize.'\n\nL['Help.Window.controls'] = 'Close with X, Escape, or right-click inside the frontmost RM window. Child dialogs have their own close controls and follow the window scale. The language selector changes the workbench language; project links open a copyable address.'\n\nL['Help.Window.drafts'] = 'Most settings and source editors keep drafts until Apply. Leaving a dirty page offers Apply, Discard or Cancel; invalid fields remain visible. Profile activation and confirmed replacement, action-bar binding and diagnostic capture have their own explicit actions. Help never applies or discards edits.'\n\nL['Help.Window.help'] = 'Gold question marks open full Help for their window, page or card. Hover controls for brief tips. Help does not save settings or commit pending text; spell and item fields keep their native reference tooltips.'\n\nL['Help.Brief.full'] = 'Open full Help for these controls without applying edits.'\n\nL['Help.Brief.window'] = 'Explain window navigation, scaling, closing and drafts.'\n\nL['Help.Brief.page'] = 'Open full Help for this page without switching tabs or applying edits.'\n\nL['Help.Brief.scale'] = 'Set the workbench and child-window scale from 70% to 130%; enter a whole percentage or drag the slider.'\n\nL['Help.Brief.edit'] = 'Edit the value; Enter or leaving the field checks and accepts valid text. Page Help explains when changes are saved.'\n\nL['Help.Brief.check'] = 'Click to toggle this option. Page Help explains when changes are saved.'\n\nL['Help.Brief.control'] = 'Use this control for the current page; page Help explains its options and consequences.'\n\nL['Help.Conditions.subject_unavailable'] = 'Help for this condition is unavailable. Its registered definition is missing, disabled or waiting for required functions. Opening Help does not register pending or imported source.'\n\nL['Help.Conditions.subject_missing'] = 'This registered condition does not provide Help.'\n\nL['Help.Conditions.subject_brief'] = 'Open Help for this condition without changing its fields.'\n\nL[\"Help.Transfers.copy\"] = \"Select all export text for manual copying. This button does not send it anywhere.\"\n\nL[\"Help.Transfers.clear\"] = \"Clear the transfer text. A previous preview becomes invalid; saved settings stay unchanged.\"\n\nL[\"Help.Transfers.apply\"] = \"Import into the displayed destination. Read the destination and review requirements before continuing.\"\n\nL[\"Help.Transfers.cancel\"] = \"Close this dialog without importing its text.\"\n\nL[\"Help.Transfers.destination\"] = \"Choose a new named copy or replacement of the selected editable entry.\"\n\nL[\"Help.Transfers.name\"] = \"Set the name for a new copy. Replacement keeps the selected entry as its destination.\"\n\nL[\"Help.Transfers.preview\"] = \"Decode and validate the current text for review. Preview does not import it.\"\n\nL[\"Help.Transfers.inspect\"] = \"Show read-only validation details for the current preview.\"\n\nL[\"Help.Transfers.profile_brief\"] = \"Explain profile import destinations and when changes are saved.\"\n\nL[\"Help.Transfers.profile_overview\"] = \"Copy the text to export a profile, or paste profile text to import. The destination controls choose a new profile or replacement of the selected saved profile. Opening Help does not decode, import, or apply the text.\"\n\nL[\"Help.Transfers.profile_replace\"] = \"REPLACE applies immediately to the selected saved profile after Import. Replacing the active profile resets it and applies the imported settings; replacing another profile writes that profile. Reopen the import if the selected saved profile changes.\"\n\nL[\"Help.Transfers.profile_new\"] = \"NEW stages the imported profile in the Profiles editor. Import fills a new-profile draft; the new profile is not saved or activated until you complete the creation controls in that editor. Give it an unused name.\"\n\nL[\"Help.Transfers.source_brief\"] = \"Explain this read-only review of imported source.\"\n\nL[\"Help.Transfers.source_review\"] = \"This view shows the selected imported function or condition source, its original and destination identifiers, and available metadata. For a condition, choose a callback to inspect its text. This view and its Help do not compile, execute, accept, or register the source. Return to the bundle review to decide whether to import it.\"\n\nL[\"Help.Transfers.source_close\"] = \"Close this read-only source view and return to the bundle review.\"\n\nL[\"Help.Transfers.bundle_review\"] = \"Validate the pasted bundle and build a proposed import plan. Review does not apply the plan.\"\n\nL[\"Help.Transfers.bundle_dependencies\"] = \"Include referenced custom function dependencies when producing export text.\"\n\nL[\"Help.Transfers.bundle_brief\"] = \"Explain dependency-bundle export, review, and explicit import.\"\n\nL[\"Help.Transfers.bundle\"] = \"Export produces a function or condition bundle, optionally with its custom function dependencies. For import, paste bundle text, choose Review import, inspect the proposed identifiers and conflicts, and review source before applying. Apply import can register trusted Lua source; accept only source you intend to run. Changing the text invalidates the prior plan. Opening Help neither reviews nor applies the bundle.\"\n\nL[\"Help.Transfers.rotation_brief\"] = \"Explain rotation preview, destination, and import scope.\"\n\nL[\"Help.Transfers.rotation\"] = \"Copy the text to export the current rotation, or paste a rotation to import. Choose replacement of the selected editable rotation or a new named copy. Class and This character set the owner of a new copy; replacement keeps the original owner. The imported rotation is opened for editing after a successful import.\"\n\nL[\"Help.Transfers.rotation_preview\"] = \"Preview import validates the current text and shows an incoming comparison. It does not save the rotation. Import is enabled only for a ready preview; changing the text requires another preview. Inspect import shows read-only diagnostics, including unsupported data that prevents import.\"\n\nL[\"Help.Transfers.comparison_brief\"] = \"Explain this read-only incoming rotation comparison.\"\n\nL[\"Help.Transfers.comparison\"] = \"This view compares the saved or exported rotation with the current incoming preview. It does not apply changes. Close it to choose the destination and import from the transfer dialog. A changed preview, closed owner, or changed profile retires this comparison Help.\"\n\nL[\"Destination\"] = \"Destination\"\n",previous=""},{at=60792,current="L[\"The question mark explains the visible controls. With condition fields open, it adds that condition’s help below the fields. Undo / Redo affect the draft. Apply saves; Discard or Cancel abandons draft changes. Red borders mark invalid or incomplete data.\"] = \"The question mark opens full Help for its subject. Hover controls for brief tips. Undo / Redo affect the draft. Apply saves; Discard or Cancel abandons draft changes. Red borders mark invalid or incomplete data.\"\n",previous="L[\"The question mark explains the visible controls. With condition fields open, it adds that condition’s help below the fields. Undo / Redo affect the draft. Apply saves; Discard or Cancel abandons draft changes. Red borders mark invalid or incomplete data.\"] = true\n"}}}
rows["UI/condition_canvas.lua"]={bytes=26134,hash=3503934404,oldBytes=26273,oldHash=3805667458,edits={{at=16412,current="            if alive() then owner:ShowSubjectHelp(model,alive) end\n",previous="            if not alive() or not owner:SyncWorking() then return end\n            if model.expanded then owner.view.help[model.key]=not owner.view.help[model.key];self:Render()\n            elseif addon.ShowWorkbenchHelp then addon:ShowWorkbenchHelp(model.name or (addon.conditionDefinitions[model.type] or {}).description or L['Condition'],addon:WorkbenchInteractionHelp('condition'),owner.chrome.author:GetText()) end\n"},{at=16133,current="        card.controls.help.tooltip=L['Help.Conditions.subject_brief']\n        if addon.BindWorkbenchHelp then addon:BindWorkbenchHelp(card.controls.help,{brief=L['Help.Conditions.subject_brief'],valid=alive}) end\n",previous=""}}}
rows["UI/condition_editor.lua"]={bytes=37034,hash=709697276,oldBytes=32009,oldHash=1887750875,edits={{at=35575,current="        profile=self.db.profile,global=self.db.global,char=self.db.char,\n",previous=""},{at=21661,current="",previous="                if self.view.help[model.key] and type(definition.help)==\"function\" then definition.help(pane) end\n"},{at=16592,current="",previous="            if self.view.help[model.key] then\n                card.helpText=card.helpText or card.fields:CreateFontString(nil,'OVERLAY','GameFontHighlightSmall')\n                card.helpText:ClearAllPoints();card.helpText:SetPoint('TOPLEFT',0,-36);card.helpText:SetJustifyH('LEFT');card.helpText:SetWordWrap(true);card.helpText:SetWidth(model.width-82)\n                card.helpText:SetText(L['AND requires every child; OR requires any child; NOT reverses its child. Unavailable data remains unavailable.']);card.helpText:Show()\n                self.view.detailsHeights[model.key]=card.helpText:GetStringHeight()+44\n            end\n"},{at=6743,current="    function shell:ShowSubjectHelp(model,cardAlive)\n        local active=self.active\n        if not active or not cardAlive() then return end\n        local working=active.working\n        local path=copyPath(model.fieldPath or model.path)\n        local node=at(working,path)\n        if type(node)~='table' then return end\n        local tag=node.type\n        local definitions=addon.conditionDefinitions\n        local revision=addon.conditionRegistryVersion\n        local definition=definitions and rawget(definitions,tag)\n        local profile,global,char=active.profile,active.global,active.char\n        local function owned()\n            return self.active==active and active.working==working and cardAlive()\n                and addon.db.profile==profile and addon.db.global==global and addon.db.char==char\n                and (active.persistentOwner or active.generation==addon.configPaneGeneration)\n                and at(working,path)==node and node.type==tag\n                and addon.conditionDefinitions==definitions and addon.conditionRegistryVersion==revision\n                and (not definitions or rawget(definitions,tag)==definition)\n        end\n        local function ownerValid()\n            if not owned() then return false end\n            if active.targetValid then\n                local ok,value=pcall(active.targetValid)\n                if not ok or value~=true then return false end\n            end\n            return owned()\n        end\n        local group=tag=='AND' or tag=='OR' or tag=='NOT'\n        local available,help,initialized\n        local function current()\n            if not ownerValid() then return false end\n            if initialized and not group then\n                local now=definition and not definition.disabled and not definition.functionUnavailable and not definition.functionSuspended\n                if now~=available then return false end\n                local same=not available or definition.help==help\n                return same and ownerValid()\n            end\n            return ownerValid()\n        end\n        local request={heading=L['Condition'],valid=current}\n        request.sections=function()\n            if not ownerValid() then return {} end\n            available=definition and not definition.disabled and not definition.functionUnavailable and not definition.functionSuspended\n            help=not group and available and definition.help\n            initialized=true\n            local heading=model.name or definition and definition.description or L['Condition']\n            request.heading=addon:PlainWorkbenchName(type(heading)=='string' and heading or L['Condition'])\n            request.owner=self.chrome.author:GetText()\n            request.renderContext={customCode=definition and definition.customCode==true,conditionTag=tag}\n            if not current() then return {} end\n            if group then\n                request.render=nil\n                return {{title=L['Groups and toggles'],text=L['AND requires every child; OR requires any child; NOT reverses its child. Unavailable data remains unavailable.']}}\n            elseif not available then\n                request.render=nil\n                return {{title=L['Unavailable'],text=L['Help.Conditions.subject_unavailable']}}\n            elseif type(help)~='function' then\n                request.render=nil\n                return {{title=L['Help'],text=L['Help.Conditions.subject_missing']}}\n            end\n            return {}\n        end\n        request.render=function(parent,requestCurrent,y,width)\n            local pane,lease;local mount={height=0}\n            function mount:Release()\n                if self.released then return end;self.released=true\n                if pane and pane.rmActive and pane.rmLease==lease then addon:ReleaseConditionWidget(pane) end\n            end\n            local function paneCurrent() return not pane or pane.rmActive and pane.rmLease==lease end\n            local function live()\n                if mount.released or not paneCurrent() or not current() or not requestCurrent() then return false end\n                return not mount.released and paneCurrent()\n            end\n            local ok,why=pcall(function()\n                if not live() then return end\n                pane=addon:CreateConditionGroup();lease=pane.rmLease\n                if not live() then return end\n                pane.frame:SetParent(parent);pane.frame:ClearAllPoints();pane.frame:SetPoint('TOPLEFT',0,-y)\n                pane:SetWidth(width);pane:SetLayout('List')\n                if not live() then return end\n                help(pane)\n                if not live() then return end\n                local function guardCallbacks(widget)\n                    local widgetLease=widget.rmLease\n                    local callbacks={};for event,callback in pairs(widget.events or widget.callbacks or {}) do callbacks[event]=callback end\n                    for event,callback in pairs(callbacks) do if type(callback)=='function' then\n                        widget:SetCallback(event,function(...) if live() and widget.rmActive and widget.rmLease==widgetLease then return callback(...) end end)\n                    end end\n                    for _,child in ipairs(widget.children or {}) do guardCallbacks(child) end\n                end\n                guardCallbacks(pane);pane:DoLayout()\n                if live() then mount.height=pane.frame:GetHeight() end\n            end)\n            if not ok or not live() then mount:Release() end\n            if not ok then error(why,0) end\n            return mount\n        end\n        local open=rawget(addon,'OpenWorkbenchHelp')\n        if type(open)=='function' then return open(addon,request) end\n    end\n",previous=""}}}
rows["UI/config.lua"]={bytes=21870,hash=1018969641,oldBytes=20823,oldHash=3041970007,edits={{at=16861,current="            if not tab.help then tab.help=addon:CreateWorkbenchHelpButton(tab,L['Help']);tab.help:SetPoint('RIGHT',-1,0) end\n            local text=tab:GetFontString();text:ClearAllPoints();text:SetPoint('LEFT',8,0)\n            local function current()return self.frame:IsShown() and self.tabGeneration==generation end\n            addon:SetUIScript(tab.help,'OnClick',addon:GuardWorkbenchHelp(current,function()self:ShowHelp(key)end))\n            addon:BindWorkbenchHelp(tab.help,{brief=L['Help.Brief.page'],valid=current})\n            addon:BindWorkbenchHelp(tab,{brief=descriptions[key],valid=current})\n",previous=""},{at=16732,current="            tab:SetSize(math.min(180,math.max(64,tab:GetFontString():GetStringWidth()+42)),22)\n",previous="            tab:SetSize(math.min(180,math.max(64,tab:GetFontString():GetStringWidth()+18)),22)\n"},{at=16205,current="        self.tabGeneration=(self.tabGeneration or 0)+1;local generation=self.tabGeneration\n",previous=""},{at=13943,current="    addon:BindWorkbenchHelp(shell.help,{brief=L['Help.Brief.window'],valid=function()return window:IsShown()end})\n    for _,control in ipairs({shell.scaleSlider,shell.scaleValue})do addon:BindWorkbenchHelp(control,{brief=L['Help.Brief.scale'],valid=function()return window:IsShown()end})end\n",previous=""},{at=13381,current="    function shell:ShowHelp(topic)\n        local heading=topic and (topic=='ItemSets' and L['Item Sets'] or L[topic]) or L['Workbench Help']\n        self.helpDialog=addon:OpenWorkbenchHelp({heading=heading,owner=addon.pretty_name,\n            valid=function()return self.frame:IsShown()end,\n            sections=function()return topic and addon:WorkbenchPageHelp(topic) or addon:WorkbenchWindowHelp()end})\n        if self.helpDialog then self.helpPane=self.helpDialog.frame end\n",previous="    function shell:ShowHelp()\n        local heading=self.section=='ItemSets' and L['Item Sets'] or L[self.section] or L['Help']\n        if self.helpDialog and self.helpDialog.frame:IsShown() and self.helpDialog.heading==heading then self:CloseHelp();return end\n        self.helpDialog=addon:ShowWorkbenchHelp(heading,addon:WorkbenchPageHelp(self.section),addon.pretty_name)\n        self.helpPane=self.helpDialog.frame\n"},{at=5800,current="    shell.help=addon:CreateWorkbenchHelpButton(window,L[\"Help\"]);shell.help:SetPoint(\"TOPRIGHT\",-31,-5);shell.help:SetSize(20,20);shell.help.icon:SetSize(18,18)\n",previous="    shell.help=addon:CreateWorkbenchHelpButton(window,L[\"Help\"]);shell.help:SetPoint(\"TOPRIGHT\",-31,-5);shell.help:SetSize(20,20);shell.help.icon:SetSize(16,16)\n"}}}
