rows["UI/function_bundle_transfer.lua"]={bytes=16439,hash=2749059124,oldBytes=14902,oldHash=4281164234,edits={{at=14770,current="    d.frame:SetFrameLevel(p.frame:GetFrameLevel()+250);d.frame:Show();d:Export();if options.text then d.input:SetText(options.text);d:Review() end;addon:RegisterWindowForEscape(d)\n    local briefs=self:TransferHelpBriefs();briefs.review=L['Help.Transfers.bundle_review'];briefs.includeDependencies=L['Help.Transfers.bundle_dependencies']\n    local sourceEvidence=self:CopySettingsData(source)\n    self:BindTransferHelp(d,{heading=L['Function dependency bundle'],owner=source and source.name or id,brief=L['Help.Transfers.bundle_brief'],sections={{title=L['Import/Export'],text=L['Help.Transfers.bundle']},{title=L['Review source'],text=L['Help.Transfers.source_review']}},briefs=briefs,valid=function() return d.exportSource==source and addon:SettingsDataEqual(source,sourceEvidence) end},valid)\n    return d\n",previous="    d.frame:SetFrameLevel(p.frame:GetFrameLevel()+250);d.frame:Show();d:Export();if options.text then d.input:SetText(options.text);d:Review() end;addon:RegisterWindowForEscape(d);return d\n"},{at=4792,current="    view.frame:SetFrameLevel(owner.frame:GetFrameLevel()+10);view.frame:Show();self:RegisterWindowForEscape(view)\n    self:BindTransferHelp(view,{heading=L['Review source'],owner=row.originalName,brief=L['Help.Transfers.source_brief'],sections={{title=L['Read-only'],text=L['Help.Transfers.source_review']}},briefs={close=L['Help.Transfers.source_close'],xClose=L['Help.Transfers.source_close']}},helpValid)\n    return view\n",previous="    view.frame:SetFrameLevel(owner.frame:GetFrameLevel()+10);view.frame:Show();self:RegisterWindowForEscape(view);return view\n"},{at=3897,current="    local plan=owner.plan;local sourceEvidence=self:CopySettingsData(source)\n    local originalID,destinationID,kind=row.originalID,row.destinationID,row.kind\n    local function helpValid()\n        if not valid() or owner.sourceReview~=view or owner.plan~=plan or row.originalID~=originalID or row.destinationID~=destinationID or row.kind~=kind then return false end\n        local found=false;for _,candidate in ipairs(owner.lastRows or {}) do if candidate==row then found=true;break end end\n        return found and (row.originalSource or row.source)==source and addon:SettingsDataEqual(source,sourceEvidence)\n    end\n",previous=""}}}
rows["UI/help.lua"]={bytes=27348,hash=299157396,oldBytes=21582,oldHash=3748524502,edits={{at=21643,current="    d.frame.rmHelpCurrent=current\n",previous=""},{at=20555,current="    if not current() then return end\n    if request.render then\n        local ok,mount=callHelpContext(request.renderContext,request.render,d.child,current,y,490)\n        local height,release\n        -- Accessors may open newer Help: consume once before publishing ownership.\n        local readable=ok and type(mount)=='table' and callHelpContext(request.renderContext,function()release=mount.Release;if current() then height=mount.height end end)\n        if not readable or not current() or type(height)~='number' or height~=height or height<0 or height==math.huge or type(release)~='function' then\n            if type(release)=='function' then callHelpContext(request.renderContext,release,mount) end\n            if current() then d.frame:Hide() end\n            return\n        end\n        d.mount=mount;d.mountRelease=release;d.mountContext=request.renderContext;y=y+height\n    end\n    if not current() then return end\n",previous=""},{at=19767,current="    if not current() then return end\n",previous=""},{at=19581,current="    d:ReleaseMount();if not current() then return end\n",previous=""},{at=19416,current="        frame:Hide();addon:SetUIScript(frame,'OnHide',function()helpRequest=helpRequest+1;frame.rmHelpCurrent=nil;d:ReleaseMount()end);addon.HideOnEscape(d)\n",previous="        frame:Hide();addon.HideOnEscape(d)\n"},{at=19110,current="        function d:ReleaseMount()\n            local mount,release,context=self.mount,self.mountRelease,self.mountContext;self.mount=nil;self.mountRelease=nil;self.mountContext=nil\n            if release then callHelpContext(context,release,mount) end\n        end\n",previous=""},{at=17802,current="function addon:ShowWorkbenchHelp(heading,sections,owner,request)\n    if not request then helpRequest=helpRequest+1;local token=helpRequest;request={current=function()return token==helpRequest end} end\n    local current=request.current\n    if not current() then return end\n",previous="function addon:ShowWorkbenchHelp(heading,sections,owner)\n"},{at=17702,current="    result[#result+1]=section(L['Window controls'],L['Help.Window.controls'])\n",previous="    result[#result+1]=section(L['Window controls'],L['Drag the title bar to move. Set Scale with the top-left slider; child windows follow it. The question mark toggles Help. Close with X, Escape, or right-click in the content area.'])\n"},{at=11400,current="        section(L['Window controls'],L['Help.Window.controls'])} end\n",previous="        section(L['Window controls'],L['Drag the title bar to move. Set Scale with the top-left slider; child windows follow it. The question mark toggles Help. Close with X, Escape, or right-click in the content area.'])} end\n"},{at=153,current="-- Help owns a document lease, never an edit/history transaction.\nlocal helpRequest=0\n---@return boolean, any\nlocal function callHelpContext(context,callback,...)\n    if addon.Diagnostics then return addon.Diagnostics:Call(context or {module='help',operation='render'},callback,...) end\n    return pcall(callback,...)\nend\nlocal function callHelp(callback,...) return callHelpContext(nil,callback,...) end\nlocal function validHelp(valid)\n    if not valid then return true end\n    local ok,current=callHelp(valid);return ok and current==true\nend\nfunction addon:GuardWorkbenchHelp(valid,callback)\n    return function(...) if validHelp(valid) then return callback(...) end end\nend\nfunction addon:OpenWorkbenchHelp(request)\n    local valid=request.valid;local previous=helpRequest\n    if not validHelp(valid) or previous~=helpRequest then return end\n    helpRequest=helpRequest+1;local token=helpRequest\n    local function current()\n        if token~=helpRequest then return false end\n        local live=validHelp(valid);return live and token==helpRequest\n    end\n    local function failed()\n        local d=self.helpWindow\n        if token==helpRequest and d then d:ReleaseMount();if token==helpRequest then d.frame:Hide() end end\n    end\n    if not current() then failed();return end\n    local sections=request.sections or {}\n    if type(sections)=='function' then local ok,value=callHelp(sections);if not ok or not current() then failed();return end;sections=value end\n    if type(sections)~='table' or not current() then failed();return end\n    local heading=request.heading or L['Help']\n    -- Capture only diagnostic scalars from the accepted subject, per request.\n    local metadata=request.renderContext\n    local context={module='help',operation='render',customCode=type(metadata)=='table' and rawget(metadata,'customCode')==true,\n        conditionTag=type(metadata)=='table' and rawget(metadata,'conditionTag') or nil}\n    local document=self:ShowWorkbenchHelp(heading,sections,request.owner,{current=current,render=request.render,renderContext=context})\n    if not document or not current() then return end\n    local handle={frame=document.frame,heading=heading,sections=sections}\n    function handle:Hide()if token==helpRequest then document:Hide()end end\n    return handle\nend\nfunction addon:WorkbenchWindowHelp()\n    return {\n        section(L['Navigation'],L['Help.Window.navigation']),\n        section(L['Scale'],L['Help.Window.scale']),\n        section(L['Window controls'],L['Help.Window.controls']),\n        section(L['Apply / Discard'],L['Help.Window.drafts']),\n        section(L['Help'],L['Help.Window.help']),\n    }\nend\n-- Descriptors are held only by their owning control and retired on pool reuse.\nfunction addon:BindWorkbenchHelp(control,descriptor)\n    if control.rmHelpBinding then control.rmHelpBinding.clear() end\n    local binding={};control.rmHelpBinding=binding\n    local enter,leave=control:GetScript('OnEnter'),control:GetScript('OnLeave')\n    local function current()return control.rmHelpBinding==binding and validHelp(descriptor.valid) and control.rmHelpBinding==binding end\n    local function onEnter(...)\n        if not current() then return end\n        if enter then enter(...) end\n        if not current() or not descriptor.brief or not GameTooltip then return end\n        if GameTooltip:IsOwned(control) then if descriptor.brief~=control.tooltip then GameTooltip:AddLine(descriptor.brief,1,1,1,true) end\n        else GameTooltip:SetOwner(control,'ANCHOR_RIGHT');GameTooltip:SetText(descriptor.brief,1,1,1,1,true) end\n        GameTooltip:Show()\n    end\n    local function onLeave(...)\n        if not current() then return end\n        if leave then leave(...) end\n        if current() and GameTooltip and GameTooltip:IsOwned(control) then GameTooltip:Hide() end\n    end\n    addon:SetUIScript(control,'OnEnter',onEnter);local installedEnter=control:GetScript('OnEnter')\n    addon:SetUIScript(control,'OnLeave',onLeave);local installedLeave=control:GetScript('OnLeave')\n    function binding.clear()\n        if control.rmHelpBinding~=binding then return end\n        control.rmHelpBinding=nil\n        if control:GetScript('OnEnter')==installedEnter then control:SetScript('OnEnter',enter) end\n        if control:GetScript('OnLeave')==installedLeave then control:SetScript('OnLeave',leave) end\n        if GameTooltip and GameTooltip:IsOwned(control) then GameTooltip:Hide() end\n    end\n    return binding.clear\nend\n",previous=""}}}
rows["UI/settings_form.lua"]={bytes=35570,hash=1062779351,oldBytes=34167,oldHash=501237137,edits={{at=32505,current="        self.builder(self);if self.DraftActions then self:DraftActions() end;self:BindHelpBriefs();if not self.creationUsedForNew then self.creationBaseline=nil;self.creationApply=nil end;self.child:SetHeight(self.y+12);self.scroll:UpdateWorkbenchScroll()\n",previous="        self.builder(self);if self.DraftActions then self:DraftActions() end;if not self.creationUsedForNew then self.creationBaseline=nil;self.creationApply=nil end;self.child:SetHeight(self.y+12);self.scroll:UpdateWorkbenchScroll()\n"},{at=30909,current="        addon:SetUIScript(swatch,'OnEnter',self:HelpGuard(function() swatch.art:SetColorTexture(values.r,values.g,values.b,values.a) end));addon:SetUIScript(swatch,'OnLeave',self:HelpGuard(function() swatch.art:SetColorTexture(values.r,values.g,values.b,values.a) end))\n",previous="        addon:SetUIScript(swatch,'OnEnter',self:Guard(function() swatch.art:SetColorTexture(values.r,values.g,values.b,values.a) end));addon:SetUIScript(swatch,'OnLeave',self:Guard(function() swatch.art:SetColorTexture(values.r,values.g,values.b,values.a) end))\n"},{at=17235,current="        addon:SetUIScript(c,'OnEnter',self:HelpGuard(function() if selected and GameTooltip then GameTooltip:SetOwner(c,'ANCHOR_RIGHT');GameTooltip:SetHyperlink(provider.kind..':'..selected);GameTooltip:AddLine(provider.kind=='item' and L['Search or drag an item here'] or L['Search or drag a spell here']);GameTooltip:Show() elseif GameTooltip then GameTooltip:SetOwner(c,'ANCHOR_RIGHT');GameTooltip:SetText(c.dropHint:GetText()) end end))\n",previous="        addon:SetUIScript(c,'OnEnter',self:Guard(function() if selected and GameTooltip then GameTooltip:SetOwner(c,'ANCHOR_RIGHT');GameTooltip:SetHyperlink(provider.kind..':'..selected);GameTooltip:AddLine(provider.kind=='item' and L['Search or drag an item here'] or L['Search or drag a spell here']);GameTooltip:Show() elseif GameTooltip then GameTooltip:SetOwner(c,'ANCHOR_RIGHT');GameTooltip:SetText(c.dropHint:GetText()) end end))\n"},{at=1254,current="    end\n    function p:HelpGuard(callback)\n        local token=self.generation\n        local function valid()return self:Valid(token)end\n        if addon.GuardWorkbenchHelp then return addon:GuardWorkbenchHelp(valid,callback) end\n        return function(...)if valid()then return callback(...)end end\n    end\n    function p:BindHelpBriefs()\n        if not addon.BindWorkbenchHelp then return end\n        local token=self.generation;local used={};local authored={};local inputs={}\n        for _,edit in ipairs(self.edits)do inputs[edit.control]=true end\n        if self.settingsKey then\n            for _,entry in ipairs(addon:WorkbenchPageHelp(self.settingsKey))do\n                if entry.id and type(entry.text)=='string' then authored[entry.id]=entry.text:match('^(.-[.!?])%s') or entry.text end\n            end\n        end\n        for key,control in pairs(self.fields)do\n            if not used[control] then\n                used[control]=true\n                local brief=authored[key] or control.tooltip\n                if not brief then\n                    brief=control.rmCheck and L['Help.Brief.check'] or inputs[control] and L['Help.Brief.edit'] or L['Help.Brief.control']\n                end\n                self.cleanups[#self.cleanups+1]=addon:BindWorkbenchHelp(control,{brief=brief,valid=function()return self:Valid(token)end})\n            end\n        end\n",previous=""}}}
rows["UI/settings_profiles.lua"]={bytes=11740,hash=2703702999,oldBytes=11055,oldHash=1700879846,edits={{at=5828,current="            end,{canReplace=selected~=nil,selectedName=selectedName,fallbackName=L['Imported profile'],help={heading=L['Profiles'],owner=selectedName,brief=L['Help.Transfers.profile_brief'],briefs=self:TransferHelpBriefs(),\n                valid=function()\n                    if not selected then return true end\n                    local target=selectedName==db:GetCurrentProfile() and db.profile or db.profiles[selectedName]\n                    return target==selected and self:SettingsDataEqual(target,baseline)\n                end,\n                sections=function(dialog)return {{title=L['Import/Export'],text=L['Help.Transfers.profile_overview']},{title=L['Destination'],text=dialog.mode=='replace' and L['Help.Transfers.profile_replace'] or L['Help.Transfers.profile_new']}}end},originalName=function(input) local decoded=codec:Decode(input);return decoded and type(decoded.value)=='table' and decoded.value.name end})\n",previous="            end,{canReplace=selected~=nil,selectedName=selectedName,fallbackName=L['Imported profile'],originalName=function(input) local decoded=codec:Decode(input);return decoded and type(decoded.value)=='table' and decoded.value.name end})\n"}}}
rows["UI/settings_transfer.lua"]={bytes=15259,hash=2811276624,oldBytes=10806,oldHash=1773681860,edits={{at=14987,current="    d.frame:SetFrameLevel(p.frame:GetFrameLevel()+250);d.frame:Show();d.scroll.workbenchBar:SetValue(0);d.scroll:UpdateWorkbenchScroll();addon:RegisterWindowForEscape(d);if options then preview() end\n    self:BindTransferHelp(d,options and options.help,valid);return d\n",previous="    d.frame:SetFrameLevel(p.frame:GetFrameLevel()+250);d.frame:Show();d.scroll.workbenchBar:SetValue(0);d.scroll:UpdateWorkbenchScroll();addon:RegisterWindowForEscape(d);if options then preview() end;return d\n"},{at=8433,current="    addon:SetUIScript(d.frame,'OnHide',function() d.reportRequest=nil;d.input:ClearFocus() end)\n",previous="    addon:SetUIScript(d.frame,'OnHide',function() d.input:ClearFocus() end)\n"},{at=6021,current="    function d:Hide() self.reportRequest=nil;self.frame:Hide() end\n    function d:SetReport(title,value,context,help)\n        local request={};self.reportRequest=request\n        local db=addon.db;local profile,global,char=db.profile,db.global,db.char\n        local displayed=false\n        local function current()\n            local shown=not displayed or self.frame:IsShown()\n            return self.reportRequest==request and addon.db==db and db.profile==profile and db.global==global and db.char==char\n                and shown and self.reportRequest==request\n        end\n        if not current() then return end\n        local text=tostring(value or '');if not current() then return end\n        self.text=text;self.chrome:SetContext(title,L['Read-only'],context or addon.pretty_name)\n        if not current() then return end\n        self.setting=true;self.input:SetText(text)\n        if self.reportRequest~=request then return end\n        self.setting=false;if not current() then return end\n        self:Layout();if not current() then return end\n        self.frame:Show();displayed=true;if not current() then return end\n        addon:RegisterWindowForEscape(self);if not current() then return end\n        self.input:SetFocus();if not current() then return end\n        self.input:SetCursorPosition(0);if not current() then return end\n        self.input:HighlightText(0,-1);if not current() then return end\n        self.scroll.workbenchBar:SetValue(0);if not current() then return end\n        addon:BindTransferHelp(self,help,current)\n",previous="    function d:Hide() self.frame:Hide() end\n    function d:SetReport(title,value,context)\n        self.text=tostring(value or '');self.chrome:SetContext(title,L['Read-only'],context or addon.pretty_name)\n        self.setting=true;self.input:SetText(self.text);self.setting=false;self:Layout();self.frame:Show();addon:RegisterWindowForEscape(self)\n        self.input:SetFocus();self.input:SetCursorPosition(0);self.input:HighlightText(0,-1);self.scroll.workbenchBar:SetValue(0)\n"},{at=237,current="-- Optional Help belongs to one current transfer/report, not its edit actions.\nfunction addon:BindTransferHelp(d,metadata,ownerValid)\n    local previous=d.transferHelpLease\n    local profile,global,char=self.db.profile,self.db.global,self.db.char\n    if ownerValid then\n        local ok,current=pcall(ownerValid)\n        if not ok or current~=true or d.transferHelpLease~=previous\n            or self.db.profile~=profile or self.db.global~=global or self.db.char~=char then return end\n    end\n    local lease={cleanups={}};d.transferHelpLease=lease\n    if previous then for _,clear in ipairs(previous.cleanups) do clear() end end\n    if d.transferHelpLease~=lease then return end\n    if not metadata then\n        if d.help then self:SetUIScript(d.help,'OnClick',nil);d.help:Hide() end\n        return\n    end\n    local extraValid=metadata.valid\n    local function base()\n        return d.transferHelpLease==lease and not lease.hidden and addon.db.profile==profile and addon.db.global==global and addon.db.char==char\n    end\n    local function current()\n        if not base() or not d.frame:IsShown() or not base() then return false end\n        for _,valid in ipairs({ownerValid or false,extraValid or false}) do if valid then\n            local ok,value=pcall(valid);if not ok or value~=true or not base() then return false end\n        end end\n        local shown=d.frame:IsShown();return shown and base()\n    end\n    local onHide=d.frame:GetScript('OnHide')\n    if onHide==d.transferHelpHideWrapper then onHide=d.transferHelpHideOriginal end\n    d.transferHelpHideOriginal=onHide\n    self:SetUIScript(d.frame,'OnHide',function(...)\n        lease.hidden=true\n        if onHide then return onHide(...) end\n    end)\n    d.transferHelpHideWrapper=d.frame:GetScript('OnHide')\n    if not d.help then d.help=self:CreateWorkbenchHelpButton(d.frame,L['Help']) end\n    if not base() then return end\n    d.help:ClearAllPoints();d.help:SetPoint('TOPRIGHT',-31,-5);d.help:SetSize(20,20);d.help.icon:SetSize(18,18);d.help.tooltip=metadata.brief or L['Help'];d.help:Show()\n    if not base() then return end\n    local sections,heading,owner=metadata.sections,metadata.heading or L['Help'],metadata.owner\n    self:SetUIScript(d.help,'OnClick',function()\n        if d.transferHelpLease~=lease then return end\n        local open=rawget(addon,'OpenWorkbenchHelp')\n        if type(open)=='function' then return open(addon,{heading=heading,owner=owner,valid=current,sections=function()\n            if type(sections)=='function' then return sections(d) end;return sections or {}\n        end}) end\n    end)\n    if self.BindWorkbenchHelp then\n        lease.cleanups[#lease.cleanups+1]=self:BindWorkbenchHelp(d.help,{brief=d.help.tooltip,valid=current})\n        for key,brief in pairs(metadata.briefs or {}) do local control=d[key];if control then\n            lease.cleanups[#lease.cleanups+1]=self:BindWorkbenchHelp(control,{brief=brief,valid=current})\n        end end\n    end\nend\nfunction addon:TransferHelpBriefs()\n    return {copy=L['Help.Transfers.copy'],clear=L['Help.Transfers.clear'],apply=L['Help.Transfers.apply'],cancel=L['Help.Transfers.cancel'],close=L['Help.Transfers.cancel'],destination=L['Help.Transfers.destination'],name=L['Help.Transfers.name'],preview=L['Help.Transfers.preview'],inspect=L['Help.Transfers.inspect']}\nend\n",previous=""}}}
rows["UI/transfer.lua"]={bytes=9566,hash=3590293502,oldBytes=8505,oldHash=3763098304,edits={{at=4330,current="    local options={valid=valid,canReplace=canReplace,selectedName=original and original.name or source and (source.body and source.body.name or source.nameKey or source.name),fallbackName=L['Imported rotation'],requirePreview=true,\n        help={heading=L['Import/Export Rotation'],brief=L['Help.Transfers.rotation_brief'],briefs=self:TransferHelpBriefs(),sections={{title=L['Import/Export'],text=L['Help.Transfers.rotation']},{title=L['Preview import'],text=L['Help.Transfers.rotation_preview']},{title=L['Applies to'],text=L['Copies belong to your Class unless This character is selected. Replacement keeps its original owner.']}}}}\n",previous="    local options={valid=valid,canReplace=canReplace,selectedName=original and original.name or source and (source.body and source.body.name or source.nameKey or source.name),fallbackName=L['Imported rotation'],requirePreview=true}\n"},{at=1907,current="    p.cleanups[#p.cleanups+1]=function() if d.serial==serial then d.frame:Hide() end end;d.frame:Show();self:RegisterWindowForEscape(d)\n    if self.BindTransferHelp then\n        local generation=p.generation;local graphLease=graph.rmLease;local evidence=self:CopySettingsData(view)\n        self:BindTransferHelp(d,{heading=L['Import comparison'],brief=L['Help.Transfers.comparison_brief'],sections={{title=L['Read-only'],text=L['Help.Transfers.comparison']}},briefs={close=L['Help.Transfers.cancel']}},function()\n            return p.importPreview==d and d.serial==serial and p.generation==generation and (not p.Valid or p:Valid(generation))\n                and d.graph==graph and graph.rmActive and graph.rmLease==graphLease and addon:SettingsDataEqual(view,evidence)\n        end)\n    end\n    return d\n",previous="    p.cleanups[#p.cleanups+1]=function() if d.serial==serial then d.frame:Hide() end end;d.frame:Show();self:RegisterWindowForEscape(d);return d\n"}}}
rows["UI/window.lua"]={bytes=13035,hash=2243813230,oldBytes=12413,oldHash=3669508627,edits={{at=12693,current="    if help then\n        chrome.help=self:CreateWorkbenchHelpButton(frame,L['Help']);chrome.help:SetPoint('TOPRIGHT',-31,-5)\n        self:SetUIScript(chrome.help,'OnClick',function()return addon:OpenWorkbenchHelp(help)end)\n        self:BindWorkbenchHelp(chrome.help,{brief=L['Help.Brief.full'],valid=help.valid})\n    end\n",previous=""},{at=9120,current="function addon:CreateWorkbenchDialogChrome(frame,title,help)\n",previous="function addon:CreateWorkbenchDialogChrome(frame,title)\n"},{at=7039,current="        -- The existing visible-dialog observer also retires owner-bound Help.\n        local current=frame.rmHelpCurrent\n        if current then\n            local ok,live=pcall(current)\n            if (not ok or not live) and frame.rmHelpCurrent==current then frame:Hide();return end\n        end\n",previous=""}}}
rows["docs/settings-workbench.md"]={bytes=8293,hash=2821571008,oldBytes=8061,oldHash=2128862552,edits={{at=4952,current="Help is a compact formatted native article with the same chrome, Help at the top right, X/Escape/right-click closure, and no report-copy or extra Close controls. Main-window Help explains navigation, scale, window controls and drafts. Every main tab has a gold Help icon for its authored page documentation, without switching tabs or applying pending text. Hover tips use shared pooled-control bindings and preserve native spell/item reference tooltips. General fields follow the same order as the page, without separate question marks beside controls. The authored text is shared data used by both renderers. Rotation/cooldown/branch Help describes clickable elements and drag/edit behavior. A condition card’s summary Help explains its interactions; with fields open, Help appends that condition’s specific help beneath those fields. Diagnostic and full-expression copy dialogs remain separate.\n",previous="Help is a compact formatted native article with the same chrome, Help at the top right, X/Escape/right-click closure, and no report-copy or extra Close controls. Main-window Help includes the authored field documentation. General fields follow the same order as the page, without separate question marks beside controls. The authored text is shared data used by both renderers. Rotation/cooldown/branch Help describes clickable elements and drag/edit behavior. A condition card’s summary Help explains its interactions; with fields open, Help appends that condition’s specific help beneath those fields. Diagnostic and full-expression copy dialogs remain separate.\n"}}}
