rows["tools/check"]={bytes=38672,hash=4224549340,oldBytes=37820,oldHash=2764795357,edits={{at=36033,current="            ['lua5.1', 'tests/help_routing.lua'],\n            ['luajit', 'tests/help_routing.lua'],\n            ['lua5.1', 'tests/condition_subject_help.lua'],\n            ['luajit', 'tests/condition_subject_help.lua'],\n            ['lua5.1', 'tests/help_diagnostics.lua'],\n            ['luajit', 'tests/help_diagnostics.lua'],\n",previous=""},{at=29729,current="            ['lua5.1', 'tests/transfer_subject_help.lua'],\n            ['luajit', 'tests/transfer_subject_help.lua'],\n            ['lua5.1', 'tests/transfer_report_help_ownership.lua'],\n            ['luajit', 'tests/transfer_report_help_ownership.lua'],\n            ['lua5.1', 'tests/transfer_help_composed_predecessor.lua'],\n            ['luajit', 'tests/transfer_help_composed_predecessor.lua'],\n            ['lua5.1', 'tests/help_combined_predecessor.lua'],\n            ['luajit', 'tests/help_combined_predecessor.lua'],\n",previous=""}}}
local function hash(s)local n=5381;for i=1,#s do n=(n*33+s:byte(i))%4294967296 end;return n end
return function(text,path)
 text=outer(text,path,'help')
 local r=assert(rows[path],'unknown composed Help inverse path')
 assert(#text==r.bytes and hash(text)==r.hash,'unrelated composed Help source: '..path)
 for _,change in ipairs(r.edits)do
  assert(text:sub(change.at,change.at+#change.current-1)==change.current,'composed Help inverse hunk mismatch')
  text=text:sub(1,change.at-1)..change.previous..text:sub(change.at+#change.current)
 end
 assert(#text==r.oldBytes and hash(text)==r.oldHash,'composed Help predecessor mismatch: '..path)
 return text
end
